 "content": "def transform(grid):
    """Draw a downward V of 2s from the lone marker, then fill the
    interior diagonal lattice c-r == seed_column (mod 4) with 1s.
    """
    n = len(grid[0])
    seed = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        left, right = seed - r, seed + r
        for c in range(n):
            if c == left or c == right:
                out[r][c] = 2
            elif left < c < right and (c - r - seed) % 4 == 0:
                out[r][c] = 1
    return out
